#!/usr/bin/env sh
set -eu
ROOT_DIR="$(CDPATH= cd -- "$(dirname -- "$0")/../.." && pwd)"
COMPOSE_FILE="${COMPOSE_FILE:-$ROOT_DIR/infra/docker/docker-compose.yml}"
POSTGRES_USER="${POSTGRES_USER:-jinhu}"
: "${POSTGRES_DB:?POSTGRES_DB is required}"
docker compose -f "$COMPOSE_FILE" exec -T postgres psql -X -v ON_ERROR_STOP=1 -U "$POSTGRES_USER" -d "$POSTGRES_DB" <<'SQL'
BEGIN;
INSERT INTO sys_org(id,tenant_id,park_id,org_code,org_name,org_type)SELECT '26100000-0000-4000-8000-000000000000',tenant_id,park_id,'T6-TALENT-ORG','人才测试组织','department' FROM sys_user WHERE is_deleted=false GROUP BY tenant_id,park_id HAVING count(*)>=2 LIMIT 1;
CREATE TEMP TABLE talent_gate_ids AS SELECT o.tenant_id,o.park_id,o.id org_id,(array_agg(u.id ORDER BY u.id))[1] actor FROM sys_org o JOIN sys_user u ON u.tenant_id=o.tenant_id AND u.park_id=o.park_id WHERE o.is_deleted=false AND u.is_deleted=false GROUP BY o.tenant_id,o.park_id,o.id HAVING count(u.id)>=1 LIMIT 1;
DO $$BEGIN IF NOT EXISTS(SELECT 1 FROM talent_gate_ids WHERE actor IS NOT NULL)THEN RAISE EXCEPTION 'talent gate baseline missing';END IF;END$$;
INSERT INTO hr_position(id,tenant_id,park_id,org_id,position_code,position_name)SELECT '26100000-0000-4000-8000-000000000001',tenant_id,park_id,org_id,'T6-TALENT-POS','关键岗位' FROM talent_gate_ids;
INSERT INTO hr_employee(id,tenant_id,park_id,employee_code,full_name,primary_org_id,position_id,employment_status)SELECT '26100000-0000-4000-8000-000000000002',tenant_id,park_id,'T6-TALENT-EMP','人才员工',org_id,'26100000-0000-4000-8000-000000000001','active' FROM talent_gate_ids;
CREATE TEMP TABLE talent_online_before AS SELECT (SELECT count(*) FROM hr_payroll_run) payroll,(SELECT count(*) FROM hr_payslip) payslip,(SELECT count(*) FROM hr_performance_cycle_employee) performance,(SELECT employment_status FROM hr_employee WHERE id='26100000-0000-4000-8000-000000000002') employee_status;
INSERT INTO hr_talent_profile_snapshot(id,tenant_id,park_id,employee_id,snapshot_no,as_of_date,employee_snapshot,performance_source,feedback_source,source_digest,created_by)SELECT '26110000-0000-4000-8000-000000000001',tenant_id,park_id,'26100000-0000-4000-8000-000000000002',1,'2026-08-25','{"employeeCode":"T6-TALENT-EMP","fullName":"人才员工"}','{"cycleId":"confirmed-v1","score":"88"}','{"subjectId":"published-v1"}',repeat('a',64),actor FROM talent_gate_ids;
INSERT INTO hr_talent_review_session(id,tenant_id,park_id,session_code,session_name,review_date,status,performance_definition,potential_definition,participant_snapshot,created_by,activated_at)SELECT '26120000-0000-4000-8000-000000000001',tenant_id,park_id,'T6-TALENT-REVIEW','人才盘点','2026-08-25','active','{"source":"confirmed"}','{"scale":"v1"}',jsonb_build_array(jsonb_build_object('userId',actor)),actor,now() FROM talent_gate_ids;
INSERT INTO hr_talent_review_subject(id,tenant_id,park_id,session_id,employee_id,profile_snapshot_id,employee_snapshot,source_snapshot)SELECT '26130000-0000-4000-8000-000000000001',tenant_id,park_id,'26120000-0000-4000-8000-000000000001','26100000-0000-4000-8000-000000000002','26110000-0000-4000-8000-000000000001','{"employeeCode":"T6-TALENT-EMP"}','{"profileSnapshotNo":1}' FROM talent_gate_ids;
INSERT INTO hr_talent_review_decision(id,tenant_id,park_id,subject_id,decision_no,performance_band,potential_band,nine_box,potential_score,reason,evidence,decided_by)SELECT '26140000-0000-4000-8000-000000000001',tenant_id,park_id,'26130000-0000-4000-8000-000000000001',1,'high','high','high_high',90,'盘点会一致确认','[{"type":"meeting"}]',actor FROM talent_gate_ids;
INSERT INTO hr_critical_position(id,tenant_id,park_id,position_id,criticality,risk_level,risk_reason,created_by)SELECT '26150000-0000-4000-8000-000000000001',tenant_id,park_id,'26100000-0000-4000-8000-000000000001','critical','high','岗位连续性风险较高',actor FROM talent_gate_ids;
INSERT INTO hr_succession_candidate_version(id,tenant_id,park_id,critical_position_id,employee_id,version_no,readiness,risk_level,risk_reason,profile_snapshot_id,created_by)SELECT '26160000-0000-4000-8000-000000000001',tenant_id,park_id,'26150000-0000-4000-8000-000000000001','26100000-0000-4000-8000-000000000002',1,'ready_1_2_years','medium','需要完成岗位轮岗','26110000-0000-4000-8000-000000000001',actor FROM talent_gate_ids;
INSERT INTO hr_development_plan(id,tenant_id,park_id,employee_id,profile_snapshot_id,plan_code,plan_name,development_goal,start_date,end_date,status,created_by)SELECT '26170000-0000-4000-8000-000000000001',tenant_id,park_id,'26100000-0000-4000-8000-000000000002','26110000-0000-4000-8000-000000000001','T6-IDP','个人发展计划','完成关键岗位轮岗','2026-08-25','2027-08-25','active',actor FROM talent_gate_ids;
INSERT INTO hr_development_plan_history(tenant_id,park_id,plan_id,event_no,event_type,to_status,actor_user_id)SELECT tenant_id,park_id,'26170000-0000-4000-8000-000000000001',1,'created','active',actor FROM talent_gate_ids;
INSERT INTO hr_development_action(id,tenant_id,park_id,plan_id,action_no,action_name,owner_employee_id,due_date,created_by)SELECT '26180000-0000-4000-8000-000000000001',tenant_id,park_id,'26170000-0000-4000-8000-000000000001',1,'完成轮岗','26100000-0000-4000-8000-000000000002','2027-01-31',actor FROM talent_gate_ids;
INSERT INTO hr_development_action_history(tenant_id,park_id,action_id,event_no,event_type,to_status,actor_user_id)SELECT tenant_id,park_id,'26180000-0000-4000-8000-000000000001',1,'created','pending',actor FROM talent_gate_ids;
DO $$BEGIN
 BEGIN UPDATE hr_talent_profile_snapshot SET as_of_date='2026-08-26' WHERE id='26110000-0000-4000-8000-000000000001';RAISE EXCEPTION 'profile mutation accepted';EXCEPTION WHEN OTHERS THEN IF SQLERRM='profile mutation accepted' THEN RAISE;END IF;END;
 BEGIN DELETE FROM hr_talent_review_decision WHERE id='26140000-0000-4000-8000-000000000001';RAISE EXCEPTION 'decision deletion accepted';EXCEPTION WHEN OTHERS THEN IF SQLERRM='decision deletion accepted' THEN RAISE;END IF;END;
 BEGIN INSERT INTO hr_talent_review_decision(tenant_id,park_id,subject_id,decision_no,performance_band,potential_band,nine_box,potential_score,reason,evidence,decided_by)SELECT tenant_id,park_id,'26130000-0000-4000-8000-000000000001',1,'low','low','low_low',1,'重复决议号码','[]',actor FROM talent_gate_ids;RAISE EXCEPTION 'duplicate decision accepted';EXCEPTION WHEN OTHERS THEN IF SQLERRM='duplicate decision accepted' THEN RAISE;END IF;END;
 BEGIN UPDATE hr_succession_candidate_version SET readiness='ready_now' WHERE id='26160000-0000-4000-8000-000000000001';RAISE EXCEPTION 'succession mutation accepted';EXCEPTION WHEN OTHERS THEN IF SQLERRM='succession mutation accepted' THEN RAISE;END IF;END;
END$$;
UPDATE hr_development_action SET status='in_progress' WHERE id='26180000-0000-4000-8000-000000000001';
UPDATE hr_development_action SET status='completed',completion_note='轮岗完成',evidence='[{"type":"completion"}]',completed_at=now() WHERE id='26180000-0000-4000-8000-000000000001';
DO $$BEGIN BEGIN UPDATE hr_development_action SET status='in_progress' WHERE id='26180000-0000-4000-8000-000000000001';RAISE EXCEPTION 'terminal action mutation accepted';EXCEPTION WHEN OTHERS THEN IF SQLERRM='terminal action mutation accepted' THEN RAISE;END IF;END;END$$;
DO $$DECLARE b record;BEGIN SELECT * INTO b FROM talent_online_before;IF b.payroll<>(SELECT count(*) FROM hr_payroll_run)OR b.payslip<>(SELECT count(*) FROM hr_payslip)OR b.performance<>(SELECT count(*) FROM hr_performance_cycle_employee)OR b.employee_status<>(SELECT employment_status FROM hr_employee WHERE id='26100000-0000-4000-8000-000000000002')THEN RAISE EXCEPTION 'talent domain changed employee/performance/payroll facts';END IF;END$$;
ROLLBACK;
SELECT 'HR talent Phase4 PostgreSQL gate passed' result;
SQL
